// PANTALLA: Login con email
// ══════════════════════════════════════════════════════════════════════════════
function LoginScreen({ onVolver, onLoginOk, onIrRegistro, club }) {
  const c = club || CLUBS[0];
  const [email, setEmail] = useState("");
  const [pass, setPass] = useState("");
  const [recordar, setRecordar] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    try {
      const saved = localStorage.getItem("mgd_remember");
      if (saved) {
        const d = JSON.parse(saved);
        if (d.email) setEmail(d.email);
        if (d.password) setPass(d.password);
        setRecordar(true);
      }
    } catch(e) {}
  }, []);

  const handleLogin = async () => {
    if (!email || !pass) { setError("Introduce tu email y contrasena."); return; }
    setLoading(true); setError("");
    const res = club?.id === "internacional" ? await loginInternacional({ email, password: pass }) : await loginUsuario({ email, password: pass, clubId: club?.id || "magdalena" });
    setLoading(false);
    if (!res.ok) { setError(res.error); return; }
    if (recordar) {
      try { localStorage.setItem("mgd_remember", JSON.stringify({ email, password: pass })); } catch(e) {}
    } else {
      try { localStorage.removeItem("mgd_remember"); } catch(e) {}
    }
    try { localStorage.setItem("mgd_session", JSON.stringify({ user: res.user, clubId: club?.id || clubActual?.id || "magdalena" })); } catch(e) {}
    onLoginOk(res.user);
  };

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">
      <div className="bg-black border-b border-zinc-800 flex items-center justify-between px-5 py-3" style={{ paddingTop: "calc(0.75rem + env(safe-area-inset-top))" }}>
        <div className="flex flex-col leading-none">
          <span className="text-zinc-500 text-xs uppercase tracking-widest">{c.deporte}</span>
          <span className="text-white text-lg font-black uppercase tracking-wide">{c.nombreCorto}</span>
        </div>
        {onVolver && <button onClick={onVolver} className="text-zinc-400 text-xs hover:text-white">Volver</button>}
      </div>
      <div className="flex-1 flex items-center justify-center p-6">
        <div className="w-full max-w-sm">
          <div className="text-center mb-6">
            <h1 className="text-white text-xl font-bold mb-1">Accede a tu cuenta</h1>
            <p className="text-zinc-500 text-sm">Introduce tus credenciales</p>
          </div>
          {error && <div className="bg-red-900/40 border border-red-800 text-red-300 text-xs p-3 rounded-lg mb-4">{error}</div>}
          <div className="space-y-3">
            <Input label="Email" type="email" autoComplete="username" value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@email.com" />
            <Input label="Contrasena" type="password" autoComplete="current-password" value={pass} onChange={e => setPass(e.target.value)} placeholder="••••••••" onKeyDown={e => e.key === "Enter" && handleLogin()} />
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={recordar} onChange={e => setRecordar(e.target.checked)} className="w-4 h-4" />
              <span className="text-zinc-400 text-xs">Recordar email y contrasena</span>
            </label>
            <Btn onClick={handleLogin} disabled={loading} className="w-full justify-center">
              {loading ? "Entrando..." : "Entrar"}
            </Btn>
          </div>
          <div className="text-center mt-4">
            <span className="text-zinc-500 text-xs">No tienes cuenta? </span>
            <button onClick={onIrRegistro} className="text-red-400 text-xs hover:text-red-300">Registrate</button>
          </div>
        </div>
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// PANTALLA: Registro en 2 pasos
// ══════════════════════════════════════════════════════════════════════════════
function RegistroScreen({ onVolver, onRegistroOk, club }) {
  const c = club || CLUBS[0];
  const [paso, setPaso] = useState(1);
  const [nombre, setNombre] = useState("");
  const [email, setEmail] = useState("");
  const [pass1, setPass1] = useState("");
  const [pass2, setPass2] = useState("");
  const [rol, setRol] = useState("familiar");
  const [codigo, setCodigo] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [rolFinal, setRolFinal] = useState(null);
  const [equipoSel, setEquipoSel] = useState(TEAMS[0]);
  const [equiposDisponibles, setEquiposDisponibles] = useState(TEAMS);
  const [equiposPasswords, setEquiposPasswords] = useState({});
  const [equiposSeguidos, setEquiposSeguidos] = useState([]);
  const equipoTocadoPorUsuario = useRef(false);

  useEffect(() => {
    const prefix = c?.firestorePrefix || "cdmagdalena";
    loadEquipos(prefix).then(eqs => {
      if (eqs && eqs.length > 0) {
        const nombres = eqs.map(e => e.nombre);
        setEquiposDisponibles(nombres);
        // Solo fijamos el primero de la lista real si el usuario todavía no
        // ha tocado el desplegable a mano — si no, le pisaríamos su elección
        // en cuanto termine de cargar esta lista.
        if (!equipoTocadoPorUsuario.current) setEquipoSel(nombres[0]);
        const pwds = {};
        eqs.forEach(e => { pwds[e.nombre] = (e.password || "").toUpperCase(); });
        setEquiposPasswords(pwds);
      }
    }).catch(() => {});
  }, []);

  const irPaso2 = () => {
    if (!nombre.trim() || !email.trim()) { setError("Rellena nombre y email."); return; }
    if (pass1.length < 6) { setError("La contrasena debe tener al menos 6 caracteres."); return; }
    if (pass1 !== pass2) { setError("Las contrasenas no coinciden."); return; }
    setError(""); setPaso(2);
  };

  const handleRegistro = async () => {
    setLoading(true); setError("");
    try {
      if (rol !== "familiar") {
        const codigosEquipo = c.passwords?.equipos || {};
        const coordPwd = c.passwords?.coordinador || "";
        // Primero comprobamos contra la contraseña real del equipo (la misma
        // que se gestiona en Ajustes → Gestión del Club → Equipos); si ese
        // equipo no está ahí (equipos muy antiguos aún no migrados), caemos
        // al código fijo de clubs.js. Presidente usa el mismo código que
        // Coordinador, ya que tiene los mismos permisos.
        const codigoEquipoReal = equiposPasswords[equipoSel];
        const codigoEsperado = codigoEquipoReal !== undefined ? codigoEquipoReal : (codigosEquipo[equipoSel] || "");
        const esRolCoordinador = rol === "coordinador" || rol === "presidente";
        const codigoOk = esRolCoordinador
          ? codigo.trim().toUpperCase() === coordPwd
          : codigo.trim().toUpperCase() === codigoEsperado;
        if (!codigoOk) { setError("Codigo incorrecto para " + (esRolCoordinador ? rol : equipoSel) + "."); setLoading(false); return; }
      }
      const seguidos = rol === "entrenador"
        ? [...new Set([equipoSel, ...equiposSeguidos])]
        : (rol === "familiar" ? equiposSeguidos : []);
      const res = await registrarUsuario({ nombre, email, password: pass1, rol, equipo: rol === "entrenador" ? equipoSel : null, equiposSeguidos: seguidos, club: c?.id || "magdalena" });
      if (!res.ok) { setError(res.error); setLoading(false); return; }
      setRolFinal(rol); setPaso(3);
      setTimeout(() => onRegistroOk(res.user), 1500);
    } catch(e) {
      setError("Error al crear la cuenta: " + e.message);
    }
    setLoading(false);
  };

  const ROLES = [
    { val: "familiar", label: "Jugador / familia", desc: "Sin codigo - acceso libre" },
    { val: "entrenador", label: "Entrenador", desc: "Requiere codigo de entrenador" },
    { val: "coordinador", label: "Coordinador", desc: "Requiere codigo de coordinador" },
    { val: "presidente", label: "Presidente", desc: "Requiere codigo de coordinador" },
  ];

  return (
    <div className="min-h-screen bg-zinc-950 flex flex-col">
      <div className="bg-black border-b border-zinc-800 flex items-center justify-between px-5 py-3" style={{ paddingTop: "calc(0.75rem + env(safe-area-inset-top))" }}>
        <div className="flex flex-col leading-none">
          <span className="text-zinc-500 text-xs uppercase tracking-widest">{c.deporte}</span>
          <span className="text-white text-lg font-black uppercase tracking-wide">{c.nombreCorto}</span>
        </div>
        <button onClick={onVolver} className="text-zinc-400 text-xs hover:text-white">Volver</button>
      </div>
      <div className="flex-1 flex items-center justify-center p-6">
        <div className="w-full max-w-sm">
          <div className="flex items-center gap-2 mb-6">
            {[1,2,3].map((n,i) => (
              <React.Fragment key={n}>
                <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold ${paso > n ? "bg-red-600 text-white" : paso === n ? "bg-red-700 text-white" : "bg-zinc-800 text-zinc-500"}`}>
                  {paso > n ? "✓" : n}
                </div>
                {i < 2 && <div className={`flex-1 h-0.5 ${paso > n ? "bg-red-600" : "bg-zinc-800"}`} />}
              </React.Fragment>
            ))}
          </div>
          {error && <div className="bg-red-900/40 border border-red-800 text-red-300 text-xs p-3 rounded-lg mb-4">{error}</div>}
          {paso === 1 && (
            <div className="space-y-3">
              <h1 className="text-white text-lg font-bold mb-1">Crea tu cuenta</h1>
              <Input label="Nombre completo" value={nombre} onChange={e => setNombre(e.target.value)} placeholder="Juan Garcia" />
              <Input label="Email" type="email" autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="tu@email.com" />
              <Input label="Contrasena" type="password" autoComplete="new-password" value={pass1} onChange={e => setPass1(e.target.value)} placeholder="Minimo 6 caracteres" />
              <Input label="Repite la contrasena" type="password" autoComplete="new-password" value={pass2} onChange={e => setPass2(e.target.value)} placeholder="••••••••" onKeyDown={e => e.key === "Enter" && irPaso2()} />
              <Btn onClick={irPaso2} className="w-full justify-center">Siguiente</Btn>
            </div>
          )}
          {paso === 2 && (
            <div className="space-y-3">
              <h1 className="text-white text-lg font-bold mb-1">Cual es tu rol?</h1>
              <div className="space-y-2">
                {ROLES.map(r => (
                  <div key={r.val} onClick={() => { setRol(r.val); setCodigo(""); }}
                    className={`flex items-center gap-3 p-3 rounded-xl border cursor-pointer transition-all ${rol === r.val ? "border-red-600 bg-red-900/20" : "border-zinc-800 bg-zinc-900 hover:border-zinc-600"}`}>
                    <div className="flex-1">
                      <div className="text-white text-sm font-semibold">{r.label}</div>
                      <div className="text-zinc-500 text-xs">{r.desc}</div>
                    </div>
                    {rol === r.val && <span className="text-red-400 text-sm">✓</span>}
                  </div>
                ))}
              </div>
              {rol !== "familiar" && (
                <div className="space-y-2">
                  <Input label="Codigo de acceso" value={codigo} onChange={e => setCodigo(e.target.value.toUpperCase())} placeholder="Pidelo a tu coordinador" />
                  {rol === "entrenador" && (
                    <div className="flex flex-col gap-1">
                      <label className="text-xs text-zinc-400 uppercase tracking-wider">Tu equipo</label>
                      <select value={equipoSel} onChange={e => { equipoTocadoPorUsuario.current = true; setEquipoSel(e.target.value); }} className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm focus:outline-none focus:border-red-600 w-full">{equiposDisponibles.map(t => <option key={t}>{t}</option>)}</select>
                    </div>
                  )}
                </div>
              )}
              {(rol === "familiar" || rol === "entrenador") && (
                <div className="space-y-1.5">
                  <label className="text-xs text-zinc-400 uppercase tracking-wider">
                    {rol === "familiar" ? "¿De qué equipo(s) quieres recibir avisos?" : "Avisos de otros equipos (además del tuyo)"}
                  </label>
                  <div className="flex flex-wrap gap-1.5">
                    {equiposDisponibles.map(eq => (
                      <button type="button" key={eq}
                        onClick={() => setEquiposSeguidos(prev => prev.includes(eq) ? prev.filter(x => x !== eq) : [...prev, eq])}
                        className={`px-2.5 py-1 rounded-full text-xs border transition-all ${equiposSeguidos.includes(eq) ? "bg-red-700 border-red-500 text-white" : "bg-zinc-900 border-zinc-700 text-zinc-400"}`}>
                        {eq}
                      </button>
                    ))}
                  </div>
                </div>
              )}
              <Btn onClick={handleRegistro} disabled={loading} className="w-full justify-center">
                {loading ? "Creando cuenta..." : "Crear cuenta"}
              </Btn>
              <Btn variant="secondary" onClick={() => { setPaso(1); setError(""); }} className="w-full justify-center">Atras</Btn>
            </div>
          )}
          {paso === 3 && (
            <div className="text-center py-4">
              <div className="w-14 h-14 bg-red-700 rounded-full flex items-center justify-center text-white text-2xl mx-auto mb-4">✓</div>
              <h1 className="text-white text-xl font-bold mb-2">Cuenta creada!</h1>
              <p className="text-zinc-500 text-sm">Entrando al club...</p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}



// ══════════════════════════════════════════════════════════════════════════════
// SECCION: Banco de jugadores del club
// ══════════════════════════════════════════════════════════════════════════════
function BancoJugadoresSection({ clubActual, onAddToEquipo }) {
  const clubInfo = CLUBS.find(c => c.id === clubActual?.id) || CLUBS[0];
  const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
  const [jugadores, setJugadores] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [search, setSearch] = React.useState("");
  const [showForm, setShowForm] = React.useState(false);
  const [editJ, setEditJ] = React.useState(null);
  const [form, setForm] = React.useState({ nombre:"", fechaNac:"", dni:"", telefono:"", posicion:"", estado:"disponible", notas:"", equipoOrigen:"" });
  const [tab, setTab] = React.useState("todos");
  const [menuBanco, setMenuBanco] = React.useState(null);
  const [seleccion, setSeleccion] = React.useState([]);
  const [equiposFiltro, setEquiposFiltro] = React.useState([]);
  const toggleEquipoFiltro = (eq) => setEquiposFiltro(s => s.includes(eq) ? s.filter(x => x !== eq) : [...s, eq]);
  const toggleSel = (id) => setSeleccion(s => s.includes(id) ? s.filter(x => x !== id) : [...s, id]);
  const [filtroPosicion, setFiltroPosicion] = React.useState("");
  const [filtroAnioMin, setFiltroAnioMin] = React.useState("");
  const [filtroAnioMax, setFiltroAnioMax] = React.useState("");

  React.useEffect(() => {
    loadBancoJugadores(prefix).then(js => { setJugadores(js); setLoading(false); }).catch(() => setLoading(false));
  }, [prefix]);

  const POSICIONES = ["Portero","Defensa Central","Lateral Derecho","Lateral Izquierdo","Mediocentro","Mediapunta","Extremo Derecho","Extremo Izquierdo","Delantero"];
  const ESTADOS = ["disponible","probando","lesionado","inactivo","sin_ficha"];
  const ESTADO_COLOR = { disponible:"green", probando:"yellow", lesionado:"red", inactivo:"zinc", sin_ficha:"zinc" };

  const save = async (nuevos) => {
    await saveBancoJugadores(prefix, nuevos);
    setJugadores(nuevos);
  };

  const openForm = (j = null) => {
    setEditJ(j?.id || null);
    setForm(j ? { nombre:j.nombre||"", fechaNac:j.fechaNac||"", dni:j.dni||"", telefono:j.telefono||"", posicion:j.posicion||"", estado:j.estado||"disponible", notas:j.notas||"", equipoOrigen:j.equipoOrigen||"" } : { nombre:"", fechaNac:"", dni:"", telefono:"", posicion:"", estado:"disponible", notas:"", equipoOrigen:"" });
    setShowForm(true);
  };

  const guardarJugador = async () => {
    if (!form.nombre.trim()) return;
    let nuevos;
    if (editJ) {
      nuevos = jugadores.map(j => j.id === editJ ? { ...j, ...form } : j);
    } else {
      const nuevo = { ...form, id: Date.now().toString(), creadoEn: new Date().toISOString() };
      nuevos = [...jugadores, nuevo];
    }
    await save(nuevos);
    setShowForm(false);
    setEditJ(null);
  };

  const eliminarJugador = async (id) => {
    if (!window.confirm("Eliminar jugador?")) return;
    await save(jugadores.filter(j => j.id !== id));
  };

  const calcEdad = (fechaNac) => {
    if (!fechaNac) return "-";
    const hoy = new Date();
    const nac = new Date(fechaNac);
    return hoy.getFullYear() - nac.getFullYear() - (hoy < new Date(hoy.getFullYear(), nac.getMonth(), nac.getDate()) ? 1 : 0);
  };

  const aniosDisponibles = [...new Set(jugadores.map(j => j.fechaNac ? new Date(j.fechaNac).getFullYear().toString() : null).filter(Boolean))].sort();

  const jugadoresFiltrados = jugadores
    .filter(j => tab === "todos" ? true : j.estado === tab)
    .filter(j => !search || j.nombre.toLowerCase().includes(search.toLowerCase()))
    .filter(j => !filtroPosicion || j.posicion === filtroPosicion || (j.posicionesSecundarias && j.posicionesSecundarias.includes(filtroPosicion)))
    .filter(j => { if (!filtroAnioMin && !filtroAnioMax) return true; const anio = j.fechaNac ? new Date(j.fechaNac).getFullYear() : null; if (!anio) return false; if (filtroAnioMin && anio < parseInt(filtroAnioMin)) return false; if (filtroAnioMax && anio > parseInt(filtroAnioMax)) return false; return true; })
    .sort((a, b) => (a.fechaNac || "").localeCompare(b.fechaNac || ""));

  const [importing, setImporting] = React.useState(false);

  const actualizarFechas = async () => {
    setImporting(true);
    try {
      const dbSnap = await loadData();
      if (!dbSnap) { setImporting(false); return; }
      const todosJugadores = [];
      Object.entries(dbSnap).forEach(([equipo, datos]) => {
        if (!datos || typeof datos !== "object") return;
        [...(datos.players || []), ...(datos.probando || [])].forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (nombre) todosJugadores.push({ nombre, fechaNacimiento: p.fechaNacimiento || "", posicion: p.posicionPrincipal || p.posicion || "", posicionesSecundarias: p.positions || [], telefono: p.phone || p.telefono || p.phone2 || "", dni: p.dni || "" });
        });
      });
      let actualizados = 0;
      const nuevoBanco = jugadores.map(j => {
        const match = todosJugadores.find(p => p.nombre.toLowerCase().trim() === j.nombre.toLowerCase().trim());
        if (match && (!j.fechaNac || j.fechaNac === "") && match.fechaNacimiento) {
          actualizados++;
          return { ...j, fechaNac: match.fechaNacimiento, posicion: j.posicion || match.posicion, posicionesSecundarias: j.posicionesSecundarias?.length ? j.posicionesSecundarias : match.posicionesSecundarias, telefono: j.telefono || match.telefono, dni: j.dni || match.dni };
        }
        return j;
      });
      await saveBancoJugadores(prefix, nuevoBanco);
      setJugadores(nuevoBanco);
      alert(actualizados + " jugadores actualizados con fecha de nacimiento.");
    } catch(e) { alert("Error: " + e.message); }
    setImporting(false);
  };

  const importarDeEquipos = async () => {
    setImporting(true);
    try {
      const dbSnap = await loadData();
      if (!dbSnap) { setImporting(false); return; }
      const bancoActual = [...jugadores];
      const idsExistentes = new Set(bancoActual.map(j => j.nombre?.toLowerCase()?.trim()));
      let nuevos = 0;
      Object.entries(dbSnap).forEach(([equipo, datos]) => {
        if (!datos || typeof datos !== "object") return;
        const players = datos.players || [];
        players.forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (!nombre) return;
          if (!idsExistentes.has(nombre.toLowerCase())) {
            bancoActual.push({
              id: Date.now().toString() + Math.random().toString(36).slice(2),
              nombre,
              fechaNac: p.fechaNacimiento || p.fechaNac || p.dob || "",
              dni: p.dni || "",
              telefono: p.phone || p.telefono || p.phone2 || "",
              posicion: p.posicionPrincipal || p.posicion || "",
              posicionesSecundarias: p.positions || p.posicionesSecundarias || [],
              estado: "disponible",
              equipoOrigen: equipo,
              notas: "",
              creadoEn: new Date().toISOString()
            });
            idsExistentes.add(nombre.toLowerCase());
            nuevos++;
          }
        });
        const probando = datos.probando || [];
        probando.forEach(p => {
          const nombre = (p.name || p.nombre || "").trim();
          if (!nombre) return;
          if (!idsExistentes.has(nombre.toLowerCase())) {
            bancoActual.push({
              id: Date.now().toString() + Math.random().toString(36).slice(2),
              nombre,
              fechaNac: p.fechaNacimiento || p.fechaNac || p.dob || "",
              dni: p.dni || "",
              telefono: p.phone || p.telefono || "",
              posicion: p.posicionPrincipal || p.posicion || "",
              posicionesSecundarias: p.positions || p.posicionesSecundarias || [],
              estado: "probando",
              equipoOrigen: equipo,
              notas: "",
              creadoEn: new Date().toISOString()
            });
            idsExistentes.add(nombre.toLowerCase());
            nuevos++;
          }
        });
      });
      await saveBancoJugadores(prefix, bancoActual);
      setJugadores(bancoActual);
      alert(nuevos + " jugadores importados al banco.");
    } catch(e) {
      alert("Error al importar: " + e.message);
    }
    setImporting(false);
  };

  if (loading) return <div className="p-6 text-zinc-500 text-sm">Cargando...</div>;

  return (
    <div className="p-6 max-w-4xl">
      <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between mb-6">
        <h2 className="text-xl font-bold text-white">Banco de Jugadores</h2>
        <div className="flex gap-2 flex-wrap">
          <Btn small variant="secondary" onClick={actualizarFechas} disabled={importing}>🔄 Fechas</Btn>
          <Btn small variant="secondary" onClick={importarDeEquipos} disabled={importing}>{importing ? "Importando..." : "📥 Importar"}</Btn>
          <Btn small onClick={() => openForm()}>+ Añadir</Btn>
        </div>
      </div>

      {showForm && (
        <Card className="mb-6">
          <h3 className="text-sm font-semibold text-white mb-4">{editJ ? "Editar jugador" : "Nuevo jugador"}</h3>
          <div className="grid grid-cols-2 gap-3 mb-3">
            <Input label="Nombre completo" value={form.nombre} onChange={e => setForm({...form, nombre:e.target.value})} placeholder="Nombre y apellidos" />
            <Input label="Fecha de nacimiento" type="date" value={form.fechaNac} onChange={e => setForm({...form, fechaNac:e.target.value})} />
            <Input label="DNI / NIE" value={form.dni} onChange={e => setForm({...form, dni:e.target.value})} placeholder="12345678A" />
            <Input label="Teléfono" value={form.telefono} onChange={e => setForm({...form, telefono:e.target.value})} placeholder="+34 600 000 000" />
            <Input label="Equipo de origen" value={form.equipoOrigen} onChange={e => setForm({...form, equipoOrigen:e.target.value})} placeholder="Ej: Juvenil A" />
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Posición</label>
              <select value={form.posicion} onChange={e => setForm({...form, posicion:e.target.value})}
                className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm w-full">
                <option value="">Sin posición</option>
                {POSICIONES.map(p => <option key={p}>{p}</option>)}
              </select>
            </div>
            <div>
              <label className="text-xs text-zinc-400 uppercase tracking-wider block mb-2">Estado</label>
              <select value={form.estado} onChange={e => setForm({...form, estado:e.target.value})}
                className="bg-zinc-900 border border-zinc-700 rounded px-3 py-2 text-zinc-100 text-sm w-full">
                {ESTADOS.map(e => <option key={e}>{e}</option>)}
              </select>
            </div>
          </div>
          <Input label="Notas" value={form.notas} onChange={e => setForm({...form, notas:e.target.value})} placeholder="Observaciones..." />
          <div className="flex gap-2 mt-3">
            <Btn onClick={guardarJugador}>Guardar</Btn>
            <Btn variant="secondary" onClick={() => { setShowForm(false); setEditJ(null); }}>Cancelar</Btn>
          </div>
        </Card>
      )}

      <div className="flex gap-2 mb-4 flex-wrap">
        {["todos","disponible","probando","lesionado","inactivo"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-3 py-1.5 rounded-lg text-xs font-medium capitalize transition-all ${tab===t?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>
            {t === "todos" ? `Todos (${jugadores.length})` : `${t} (${jugadores.filter(j=>j.estado===t).length})`}
          </button>
        ))}
        <div className="w-full md:w-auto md:ml-auto flex gap-2 flex-wrap">
          <select value={filtroAnioMin} onChange={e => setFiltroAnioMin(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Desde</option>
            {aniosDisponibles.map(a => <option key={a}>{a}</option>)}
          </select>
          <select value={filtroAnioMax} onChange={e => setFiltroAnioMax(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Hasta</option>
            {aniosDisponibles.map(a => <option key={a}>{a}</option>)}
          </select>
          <select value={filtroPosicion} onChange={e => setFiltroPosicion(e.target.value)}
            className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1.5 text-zinc-100 text-xs focus:outline-none">
            <option value="">Todas las posiciones</option>
            {POSICIONES.map(p => <option key={p}>{p}</option>)}
          </select>
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Buscar jugador..."
            className="bg-zinc-900 border border-zinc-700 rounded px-3 py-1.5 text-zinc-100 text-xs w-40 focus:outline-none" />
        </div>
      </div>

      <Card>
        {jugadoresFiltrados.length === 0 && <p className="text-zinc-500 text-sm py-2">No hay jugadores.</p>}
                {(() => {
          const equiposDisponibles = [...new Set(jugadores.map(j => j.equipoOrigen || "Sin equipo"))].sort();
          if (equiposDisponibles.length <= 1) return null;
          return (
            <div className="mb-3">
              <p className="text-xs text-zinc-500 uppercase tracking-wider mb-1.5">Filtrar por equipo{equiposFiltro.length > 0 ? ` (${equiposFiltro.length})` : ""}</p>
              <div className="flex flex-wrap gap-1.5">
                {equiposDisponibles.map(eq => (
                  <button key={eq} onClick={() => toggleEquipoFiltro(eq)}
                    className={`text-xs px-3 py-1.5 rounded-full border transition-all ${equiposFiltro.includes(eq) ? "bg-red-700 border-red-500 text-white font-semibold" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                    {eq}
                  </button>
                ))}
                {equiposFiltro.length > 0 && (
                  <button onClick={() => setEquiposFiltro([])}
                    className="text-xs px-3 py-1.5 rounded-full border border-zinc-600 text-zinc-300 hover:text-white transition-all">
                    ✕ Quitar filtro
                  </button>
                )}
              </div>
            </div>
          );
        })()}
        {jugadoresFiltrados.filter(j => equiposFiltro.length === 0 || equiposFiltro.includes(j.equipoOrigen || "Sin equipo")).map(j => (
          <div key={j.id} onClick={() => setMenuBanco(j)}
            className="flex items-center gap-3 py-3 border-b border-zinc-800 last:border-0 cursor-pointer active:bg-zinc-800/50 transition-colors">
            <input type="checkbox" checked={seleccion.includes(j.id)}
              onClick={e => e.stopPropagation()}
              onChange={() => toggleSel(j.id)}
              className="w-5 h-5 accent-red-600 shrink-0 cursor-pointer" />
            <div className="w-9 h-9 rounded-full bg-zinc-700 flex items-center justify-center text-white text-sm font-bold flex-shrink-0">
              {j.nombre[0]?.toUpperCase()}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-white text-sm font-semibold truncate">{j.nombre}</div>
              <div className="text-zinc-500 text-xs truncate">
                {[j.fechaNac ? new Date(j.fechaNac).getFullYear() : null, j.posicion, j.equipoOrigen].filter(Boolean).join(" · ") || "Sin datos"}
              </div>
            </div>
            <Badge color={ESTADO_COLOR[j.estado] || "zinc"}>{j.estado}</Badge>
            <span className="text-zinc-500 text-lg shrink-0">›</span>
          </div>
        ))}
      </Card>

      {/* Barra de acciones de seleccion multiple */}
      {seleccion.length > 0 && (
        <div className="fixed bottom-20 md:bottom-6 inset-x-3 md:inset-x-auto md:right-6 z-50 bg-zinc-800 border border-zinc-600 rounded-2xl shadow-2xl p-3 flex items-center gap-2 flex-wrap md:max-w-md">
          <span className="text-white text-sm font-semibold px-1">{seleccion.length} seleccionado{seleccion.length > 1 ? "s" : ""}</span>
          <div className="flex gap-2 ml-auto">
            {onAddToEquipo && <Btn small onClick={() => {
              const elegidos = jugadores.filter(j => seleccion.includes(j.id));
              onAddToEquipo(elegidos);
              setSeleccion([]);
            }}>➕ Al equipo</Btn>}
            <Btn small variant="danger" onClick={() => {
              if (!window.confirm("¿Eliminar " + seleccion.length + " jugador(es) del banco?")) return;
              const restantes = jugadores.filter(j => !seleccion.includes(j.id));
              save(restantes);
              setSeleccion([]);
            }}>🗑️</Btn>
            <Btn small variant="ghost" onClick={() => setSeleccion([])}>✕</Btn>
          </div>
        </div>
      )}

      {/* Ficha del jugador del banco */}
      {menuBanco && (() => {
        const j = jugadores.find(x => x.id === menuBanco.id) || menuBanco;
        return (
          <div className="fixed inset-0 bg-black/70 z-[60] flex items-end md:items-center md:justify-center" onClick={() => setMenuBanco(null)}>
            <div className="bg-zinc-900 border-t border-zinc-700 md:border md:rounded-xl rounded-t-2xl w-full md:max-w-md p-5 pb-8 space-y-4 max-h-[85vh] overflow-auto" onClick={e => e.stopPropagation()}>
              <div className="w-10 h-1 bg-zinc-700 rounded-full mx-auto md:hidden" />
              <div className="text-center">
                <div className="w-14 h-14 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xl font-bold mx-auto mb-2">
                  {j.nombre[0]?.toUpperCase()}
                </div>
                <p className="text-white font-bold text-lg">{j.nombre}</p>
                <div className="mt-1"><Badge color={ESTADO_COLOR[j.estado] || "zinc"}>{j.estado}</Badge></div>
              </div>
              <div className="bg-zinc-800/60 rounded-xl p-4 space-y-1.5 text-sm">
                {j.fechaNac && <p className="text-zinc-300">🎂 {calcEdad(j.fechaNac)} años ({new Date(j.fechaNac).toLocaleDateString("es-ES")})</p>}
                {j.posicion && <p className="text-zinc-300">⚽ {j.posicion}{(j.posicionesSecundarias||[]).length > 0 ? " · " + j.posicionesSecundarias.join(", ") : ""}</p>}
                {j.telefono && <p className="text-zinc-300">📞 {j.telefono}</p>}
                {j.dni && <p className="text-zinc-300 font-mono">🪪 {j.dni}</p>}
                {j.equipoOrigen && <p className="text-zinc-400">📍 {j.equipoOrigen}</p>}
                {j.notas && <p className="text-zinc-400 italic pt-1 border-t border-zinc-700">{j.notas}</p>}
                {!j.fechaNac && !j.posicion && !j.telefono && !j.dni && <p className="text-zinc-600">Sin más datos.</p>}
              </div>
              <div className="grid grid-cols-2 gap-2">
                {onAddToEquipo && <Btn variant="secondary" onClick={() => { setMenuBanco(null); onAddToEquipo(j); }}>➕ A equipo</Btn>}
                <Btn variant="secondary" onClick={() => { setMenuBanco(null); openForm(j); }}>✏️ Editar</Btn>
                <Btn variant="danger" onClick={() => { setMenuBanco(null); eliminarJugador(j.id); }}>🗑️ Eliminar</Btn>
              </div>
              <Btn variant="ghost" className="w-full justify-center" onClick={() => setMenuBanco(null)}>Cerrar</Btn>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// SECCION: Gestión de equipos y usuarios del club
// ══════════════════════════════════════════════════════════════════════════════
function GestionClubSection({ clubActual, onEquiposChange }) {
  const clubInfo = CLUBS.find(c => c.id === clubActual?.id) || CLUBS[0];
  const prefix = clubInfo?.firestorePrefix || "cdmagdalena";
  const teamPasswordsLocal = clubInfo?.passwords?.equipos || TEAM_PASSWORDS;
  const [equipos, setEquipos] = React.useState([]);
  const [usuarios, setUsuarios] = React.useState([]);
  const [loading, setLoading] = React.useState(true);
  const [nuevoEquipo, setNuevoEquipo] = React.useState("");
  const [nuevaPassword, setNuevaPassword] = React.useState("");
  const [saving, setSaving] = React.useState(false);
  const [msg, setMsg] = React.useState("");
  const [tab, setTab] = React.useState("equipos");
  const [editandoRol, setEditandoRol] = React.useState(null); // email del usuario en edición
  const [rolSeleccionado, setRolSeleccionado] = React.useState("");
  const [guardandoRol, setGuardandoRol] = React.useState(false);

  React.useEffect(() => {
    const cargar = async () => {
      try {
        const [eq, us] = await Promise.all([
          loadEquipos(prefix).catch(() => []),
          loadUsuariosClub(prefix).catch(() => [])
        ]);
        if (eq.length === 0 && TEAMS.length > 0) {
          const migrados = TEAMS.map(nombre => ({
            nombre,
            password: Object.entries({...teamPasswordsLocal}).find(([k]) => k === nombre)?.[1] || "",
            creadoEn: new Date().toISOString()
          }));
          await saveEquipos(prefix, migrados).catch(() => {});
          setEquipos(migrados);
        } else {
          setEquipos(eq);
        }
        setUsuarios(us);
      } catch(e) {
        console.error("Error cargando gestion:", e);
      } finally {
        setLoading(false);
      }
    };
    cargar();
  }, [prefix]);

  const cambiarRol = async (usuario, clubId, nuevoRol) => {
    setGuardandoRol(true);
    const res = await actualizarRolUsuario(prefix, usuario.email, clubId, nuevoRol);
    if (res.ok) {
      setUsuarios(prev => prev.map(u => {
        if (u.email !== usuario.email) return u;
        const roles = { ...(u.roles || {}) };
        const equipoActual = roles[clubId]?.equipo || null;
        roles[clubId] = { rol: nuevoRol, equipo: nuevoRol === "entrenador" ? equipoActual : null };
        return { ...u, roles };
      }));
      setMsg("Rol actualizado.");
    } else {
      setMsg("Error al actualizar el rol: " + res.error);
    }
    setEditandoRol(null);
    setGuardandoRol(false);
  };

  const crearEquipo = async () => {
    if (!nuevoEquipo.trim() || !nuevaPassword.trim()) { setMsg("Pon nombre y contraseña."); return; }
    if (equipos.find(e => e.nombre === nuevoEquipo.trim())) { setMsg("Ya existe ese equipo."); return; }
    setSaving(true);
    const nuevo = { nombre: nuevoEquipo.trim(), password: nuevaPassword.trim().toUpperCase(), creadoEn: new Date().toISOString() };
    const nuevos = [...equipos, nuevo];
    const res = await saveEquipos(prefix, nuevos);
    if (res.ok) { setEquipos(nuevos); if (onEquiposChange) onEquiposChange(nuevos); setNuevoEquipo(""); setNuevaPassword(""); setMsg("Equipo creado."); }
    else { setMsg("Error: " + res.error); }
    setSaving(false);
    setTimeout(() => setMsg(""), 3000);
  };

  const [editando, setEditando] = React.useState(null);
  const [editNombre, setEditNombre] = React.useState("");
  const [editPassword, setEditPassword] = React.useState("");
  const [verJugadores, setVerJugadores] = React.useState(null);

  const eliminarEquipo = async (nombre) => {
    if (!window.confirm("Eliminar equipo " + nombre + "?")) return;
    const nuevos = equipos.filter(e => e.nombre !== nombre);
    await saveEquipos(prefix, nuevos);
    setEquipos(nuevos);
    if (onEquiposChange) onEquiposChange(nuevos);
  };

  const editarEquipo = (eq) => {
    setEditando(eq.nombre);
    setEditNombre(eq.nombre);
    setEditPassword(eq.password);
  };

  const guardarEdicion = async () => {
    if (!editNombre.trim() || !editPassword.trim()) return;
    const nuevos = equipos.map(e => e.nombre === editando
      ? { ...e, nombre: editNombre.trim(), password: editPassword.trim().toUpperCase() }
      : e
    );
    const sinDups = nuevos.filter((e, i, arr) => arr.findIndex(x => x.nombre === e.nombre) === i);
    await saveEquipos(prefix, sinDups);
    setEquipos(sinDups);
    if (onEquiposChange) onEquiposChange(sinDups);
    setEditando(null);
    setEditNombre("");
    setEditPassword("");
    setTimeout(() => window.location.reload(), 500);
  };

  const jugadoresDeEquipo = (nombreEquipo) => {
    return usuarios.filter(u => {
      const clubId = clubInfo?.id || "magdalena";
      const roles = u.roles || {};
      const clubRol = roles[clubId];
      const equipo = clubRol?.equipo || u.equipo || null;
      return equipo === nombreEquipo;
    });
  };

  const getRolUsuario = (u) => {
    const clubId = clubInfo?.id || "magdalena";
    const roles = u.roles || {};
    const clubRol = roles[clubId];
    return clubRol?.rol || u.rol || "familiar";
  };

  const ROL_COLOR = { coordinador: "red", presidente: "yellow", entrenador: "blue", familiar: "zinc" };

  if (loading) return <div className="p-6 text-zinc-500 text-sm">Cargando...</div>;

  return (
    <div className="p-6 max-w-3xl">
      <h2 className="text-xl font-bold text-white mb-6">Gestión del Club</h2>
      <div className="flex gap-2 mb-6">
        <button onClick={() => setTab("equipos")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${tab==="equipos"?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>Equipos</button>
        <button onClick={() => setTab("usuarios")} className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${tab==="usuarios"?"bg-red-700 text-white":"bg-zinc-800 text-zinc-400 hover:text-white"}`}>Usuarios ({usuarios.length})</button>
      </div>

      {tab === "equipos" && (
        <div>
          <Card className="mb-4">
            <h3 className="text-sm font-semibold text-white mb-3">Crear nuevo equipo</h3>
            <div className="flex gap-2 mb-2">
              <Input label="Nombre del equipo" value={nuevoEquipo} onChange={e => setNuevoEquipo(e.target.value)} placeholder="Ej: Infantil A" />
              <Input label="Contraseña" value={nuevaPassword} onChange={e => setNuevaPassword(e.target.value.toUpperCase())} placeholder="Ej: INF2026" />
            </div>
            {msg && <p className="text-xs text-green-400 mb-2">{msg}</p>}
            <Btn onClick={crearEquipo} disabled={saving}>{saving ? "Guardando..." : "Crear equipo"}</Btn>
          </Card>
          <Card>
            <h3 className="text-sm font-semibold text-white mb-3">Equipos actuales ({equipos.length})</h3>
            {equipos.length === 0 && <p className="text-zinc-500 text-sm">No hay equipos creados aun.</p>}
            {equipos.map(eq => (
              <div key={eq.nombre} className="py-2 border-b border-zinc-800 last:border-0">
                {editando === eq.nombre ? (
                  <div className="flex gap-2 items-end">
                    <Input label="Nombre" value={editNombre} onChange={e => setEditNombre(e.target.value)} />
                    <Input label="Contraseña" value={editPassword} onChange={e => setEditPassword(e.target.value.toUpperCase())} />
                    <Btn small onClick={guardarEdicion}>Guardar</Btn>
                    <Btn small variant="secondary" onClick={() => { setEditando(null); setEditNombre(""); setEditPassword(""); }}>Cancelar</Btn>
                  </div>
                ) : (
                  <div className="flex items-center gap-2">
                    <div className="flex-1">
                      <div className="text-white text-sm font-semibold">{eq.nombre}</div>
                      <div className="text-zinc-500 text-xs">Contraseña: <span className="text-zinc-300 font-mono">{eq.password}</span></div>
                    </div>
                    <Btn small variant="secondary" onClick={() => setVerJugadores(verJugadores === eq.nombre ? null : eq.nombre)}>
                      {verJugadores === eq.nombre ? "Ocultar" : "Jugadores"}
                    </Btn>
                    <Btn small onClick={() => editarEquipo(eq)}>Editar</Btn>
                    <Btn small variant="danger" onClick={() => eliminarEquipo(eq.nombre)}>Eliminar</Btn>
                  </div>
                )}
                {verJugadores === eq.nombre && (
                  <div className="mt-2 pl-3 border-l-2 border-zinc-700">
                    {jugadoresDeEquipo(eq.nombre).length === 0 ? (
                      <p className="text-zinc-600 text-xs">Sin entrenadores registrados</p>
                    ) : (
                      jugadoresDeEquipo(eq.nombre).map(u => (
                        <div key={u.email} className="flex items-center gap-2 py-1">
                          <div className="w-6 h-6 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                            {(u.nombre || u.email || "?")[0].toUpperCase()}
                          </div>
                          <div className="flex-1">
                            <div className="text-white text-xs font-semibold">{u.nombre}</div>
                            <div className="text-zinc-500 text-xs">{u.email}</div>
                          </div>
                          <Badge color={getRolUsuario(u) === "entrenador" ? "blue" : "zinc"}>{getRolUsuario(u)}</Badge>
                        </div>
                      ))
                    )}
                  </div>
                )}
              </div>
            ))}
          </Card>
        </div>
      )}

      {tab === "usuarios" && (
        <Card>
          <h3 className="text-sm font-semibold text-white mb-3">Usuarios registrados</h3>
          {msg && <p className="text-xs text-green-400 mb-2">{msg}</p>}
          {usuarios.length === 0 && <p className="text-zinc-500 text-sm">No hay usuarios registrados.</p>}
          {usuarios.map(u => (
            <div key={u.email} className="flex items-center gap-3 py-2 border-b border-zinc-800 last:border-0">
              <div className="w-8 h-8 rounded-full bg-zinc-700 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                {(u.nombre || u.email || "?")[0].toUpperCase()}
              </div>
              <div className="flex-1">
                <div className="text-white text-sm font-semibold">{u.nombre || u.email}</div>
                <div className="text-zinc-500 text-xs">{u.email}</div>
                {u.equipo && <div className="text-zinc-500 text-xs">Equipo: {u.equipo}</div>}
              </div>
              {(() => {
                const clubId = clubActual?.id || "magdalena";
                const roles = u.roles || {};
                const clubRol = roles[clubId];
                const rol = clubRol?.rol || u.rol || "familiar";
                if (editandoRol === u.email) {
                  return (
                    <div className="flex items-center gap-1.5">
                      <select value={rolSeleccionado} onChange={e => setRolSeleccionado(e.target.value)}
                        className="bg-zinc-900 border border-zinc-700 rounded px-2 py-1 text-zinc-100 text-xs focus:outline-none focus:border-red-600">
                        <option value="familiar">familiar</option>
                        <option value="entrenador">entrenador</option>
                        <option value="coordinador">coordinador</option>
                        <option value="presidente">presidente</option>
                      </select>
                      <button disabled={guardandoRol} onClick={() => cambiarRol(u, clubId, rolSeleccionado)}
                        className="text-green-400 hover:text-green-300 text-xs font-semibold disabled:opacity-50">✓</button>
                      <button disabled={guardandoRol} onClick={() => setEditandoRol(null)}
                        className="text-zinc-500 hover:text-zinc-300 text-xs disabled:opacity-50">✕</button>
                    </div>
                  );
                }
                return (
                  <button onClick={() => { setEditandoRol(u.email); setRolSeleccionado(rol); }}
                    className="flex items-center gap-1">
                    <Badge color={ROL_COLOR[rol] || "zinc"}>{rol}</Badge>
                    <span className="text-zinc-600 text-xs">✏️</span>
                  </button>
                );
              })()}
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}


// ══════════════════════════════════════════════════════════════════════════════
// COMPONENTE: Microciclo semanal
// ══════════════════════════════════════════════════════════════════════════════
function MicrocicloSection({ team, data, onSave }) {
  const DIAS = ["Lunes","Martes","Miercoles","Jueves","Viernes","Sabado","Domingo"];
  const TIPOS = ["Descanso","Fisico","Tecnico","Tactico","Mixto","Partido","Recuperacion"];
  const INTENSIDADES = ["Baja","Media","Alta","Maxima"];
  const COLORES_TIPO = {
    "Descanso":"bg-zinc-800 text-zinc-400",
    "Fisico":"bg-orange-900 text-orange-300",
    "Tecnico":"bg-blue-900 text-blue-300",
    "Tactico":"bg-purple-900 text-purple-300",
    "Mixto":"bg-yellow-900 text-yellow-300",
    "Partido":"bg-red-900 text-red-300",
    "Recuperacion":"bg-green-900 text-green-300"
  };
  const COLORES_INT = { "Baja":"text-green-400","Media":"text-yellow-400","Alta":"text-orange-400","Maxima":"text-red-400" };

  // Fechas siempre en local, nunca pasando por UTC: "new Date('2026-08-03')" lo
  // interpreta el navegador como medianoche UTC, y luego toISOString() lo vuelve
  // a convertir a UTC — cerca de medianoche esto puede desplazar el día (y en
  // casos límite el mes/año) según la zona horaria. Con estas dos funciones la
  // fecha que ves es siempre la fecha real de tu reloj, sin conversiones raras.
  const aISOLocal = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  const deISOLocal = (iso) => { const [y, m, d] = iso.split("-").map(Number); return new Date(y, m - 1, d); };

  const semanaActual = () => {
    const hoy = new Date();
    const lunes = new Date(hoy);
    lunes.setDate(hoy.getDate() - (hoy.getDay() || 7) + 1);
    return aISOLocal(lunes);
  };

  const [semana, setSemana] = React.useState(semanaActual());
  const [plan, setPlan] = React.useState(
    (data?.microciclos || {})[semanaActual()] || DIAS.map(d => ({ dia: d, tipo: "Descanso", objetivo: "", carga: 5, intensidad: "Media", notas: "" }))
  );
  const [guardando, setGuardando] = React.useState(false);

  React.useEffect(() => {
    const mc = (data?.microciclos || {})[semana];
    setPlan(mc || DIAS.map(d => ({ dia: d, tipo: "Descanso", objetivo: "", carga: 5, intensidad: "Media", notas: "" })));
  }, [semana, data]);

  const fechaISO = (i) => {
    const d = deISOLocal(semana);
    d.setDate(d.getDate() + i);
    return aISOLocal(d);
  };
  const fechaDia = (i) => deISOLocal(fechaISO(i)).toLocaleDateString("es-ES", { day: "numeric", month: "short" });

  const trainingsDe = (i) => (data?.trainings || []).filter(t => t.fecha === fechaISO(i));
  const matchesDe = (i) => (data?.matches || []).filter(m => m.fecha === fechaISO(i));

  const updateDia = (i, field, val) => {
    setPlan(plan.map((d, idx) => idx === i ? { ...d, [field]: val } : d));
  };

  const dataConPlan = (base) => ({
    ...base,
    microciclos: { ...(base?.microciclos || {}), [semana]: plan },
  });

  const guardar = async () => {
    setGuardando(true);
    await onSave(dataConPlan(data));
    setGuardando(false);
  };

  const crearSesion = async (i) => {
    const dia = plan[i];
    const nuevo = {
      id: Date.now(),
      fecha: fechaISO(i),
      desc: [dia.tipo !== "Descanso" ? "[" + dia.tipo + (dia.intensidad ? " · " + dia.intensidad : "") + "]" : "", dia.objetivo].filter(Boolean).join(" "),
      duracion: 90,
    };
    const trainings = [...(data.trainings || []), nuevo].sort((a, b) => (a.fecha || "").localeCompare(b.fecha || ""));
    setGuardando(true);
    await onSave(dataConPlan({ ...data, trainings }));
    setGuardando(false);
  };

  const crearSemana = async () => {
    const nuevos = [];
    plan.forEach((dia, i) => {
      if (dia.tipo === "Descanso" || dia.tipo === "Partido") return;
      if (trainingsDe(i).length > 0) return;
      nuevos.push({
        id: Date.now() + i,
        fecha: fechaISO(i),
        desc: ["[" + dia.tipo + (dia.intensidad ? " · " + dia.intensidad : "") + "]", dia.objetivo].filter(Boolean).join(" "),
        duracion: 90,
      });
    });
    if (!nuevos.length) { alert("Todos los días planificados ya tienen sesión creada."); return; }
    if (!window.confirm("¿Crear " + nuevos.length + " entrenamiento(s) a partir del plan?")) return;
    const trainings = [...(data.trainings || []), ...nuevos].sort((a, b) => (a.fecha || "").localeCompare(b.fecha || ""));
    setGuardando(true);
    await onSave(dataConPlan({ ...data, trainings }));
    setGuardando(false);
  };

  const semanaAnterior = () => { const d = deISOLocal(semana); d.setDate(d.getDate() - 7); setSemana(aISOLocal(d)); };
  const semanaSiguiente = () => { const d = deISOLocal(semana); d.setDate(d.getDate() + 7); setSemana(aISOLocal(d)); };

  const cargaTotal = plan.reduce((s, d) => d.tipo !== "Descanso" ? s + (d.carga || 0) : s, 0);
  const sesionesPlan = plan.filter(d => d.tipo !== "Descanso").length;
  const sesionesCreadas = plan.reduce((s, d, i) => s + trainingsDe(i).length, 0);

  return (
    <div className="max-w-5xl space-y-4">
      <div className="flex items-center justify-between flex-wrap gap-2">
        <div className="flex items-center gap-2">
          <button onClick={semanaAnterior} className="text-zinc-400 hover:text-white px-3 py-1.5 bg-zinc-800 rounded-lg">‹</button>
          <span className="text-zinc-300 text-sm font-medium">Semana {deISOLocal(semana).toLocaleDateString("es-ES", {day:"numeric",month:"short"})}</span>
          <button onClick={semanaSiguiente} className="text-zinc-400 hover:text-white px-3 py-1.5 bg-zinc-800 rounded-lg">›</button>
        </div>
        <Btn small variant="secondary" onClick={crearSemana} disabled={guardando}>⚡ Crear sesiones de la semana</Btn>
      </div>

      <div className="grid grid-cols-3 gap-2">
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{sesionesCreadas}/{sesionesPlan}</div>
          <div className="text-zinc-500 text-xs">Creadas / plan</div>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{cargaTotal}</div>
          <div className="text-zinc-500 text-xs">Carga total</div>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 rounded-xl px-3 py-2.5 text-center">
          <div className="text-white font-bold text-lg">{sesionesPlan > 0 ? (cargaTotal/sesionesPlan).toFixed(1) : 0}</div>
          <div className="text-zinc-500 text-xs">Media/sesión</div>
        </div>
      </div>

      <div className="space-y-2">
        {plan.map((dia, i) => {
          const trainsReales = trainingsDe(i);
          const matchesReales = matchesDe(i);
          return (
            <div key={i} className={`border rounded-xl p-3 ${dia.tipo === "Partido" || matchesReales.length ? "border-red-800 bg-red-900/10" : "border-zinc-800 bg-zinc-900"}`}>
              <div className="flex items-center gap-2 flex-wrap">
                <div className="w-20 flex-shrink-0">
                  <div className="text-white text-sm font-semibold">{dia.dia}</div>
                  <div className="text-zinc-500 text-xs">{fechaDia(i)}</div>
                </div>
                <select value={dia.tipo} onChange={e => updateDia(i, "tipo", e.target.value)}
                  className={`text-xs rounded-lg px-2 py-1.5 border-0 font-medium cursor-pointer ${COLORES_TIPO[dia.tipo] || "bg-zinc-800 text-zinc-300"}`}>
                  {TIPOS.map(t => <option key={t}>{t}</option>)}
                </select>
                {dia.tipo !== "Descanso" && (
                  <>
                    <input value={dia.objetivo} onChange={e => updateDia(i, "objetivo", e.target.value)}
                      placeholder="Objetivo del día..."
                      className="flex-1 min-w-28 bg-zinc-800 border border-zinc-700 rounded-lg px-2 py-1.5 text-zinc-100 text-xs focus:outline-none" />
                    <div className="flex items-center gap-1">
                      <span className="text-zinc-500 text-xs">Carga:</span>
                      <input type="range" min="1" max="10" value={dia.carga}
                        onChange={e => updateDia(i, "carga", parseInt(e.target.value))}
                        className="w-16 accent-red-600" />
                      <span className="text-white text-xs font-bold w-4">{dia.carga}</span>
                    </div>
                    <select value={dia.intensidad} onChange={e => updateDia(i, "intensidad", e.target.value)}
                      className={`text-xs bg-zinc-800 border border-zinc-700 rounded-lg px-2 py-1.5 font-medium ${COLORES_INT[dia.intensidad] || ""}`}>
                      {INTENSIDADES.map(t => <option key={t}>{t}</option>)}
                    </select>
                  </>
                )}
              </div>

              <div className="mt-2 flex items-center gap-2 flex-wrap">
                {matchesReales.map(m => (
                  <span key={m.id} className="text-xs px-2 py-1 rounded-full bg-red-900/40 border border-red-700 text-red-300">⚽ vs {m.rival}{m.resultado ? " · " + m.resultado : ""}</span>
                ))}
                {trainsReales.map(t => (
                  <span key={t.id} className="text-xs px-2 py-1 rounded-full bg-green-900/30 border border-green-700/60 text-green-300">✓ Sesión creada · {t.duracion || 90} min · {(t.tasks||[]).length} tareas</span>
                ))}
                {dia.tipo !== "Descanso" && dia.tipo !== "Partido" && trainsReales.length === 0 && (
                  <button onClick={() => crearSesion(i)} disabled={guardando}
                    className="text-xs px-2.5 py-1 rounded-full bg-zinc-800 border border-zinc-600 text-zinc-300 hover:border-zinc-400 hover:text-white transition-all">➕ Crear entrenamiento</button>
                )}
              </div>
            </div>
          );
        })}
      </div>
      <Btn onClick={guardar} disabled={guardando} className="w-full justify-center">
        {guardando ? "Guardando..." : "💾 Guardar microciclo"}
      </Btn>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════════════════════
// COMPONENTE: Barra de navegación inferior (solo móvil, 4 más recientes)
// ══════════════════════════════════════════════════════════════════════════════
function BottomNav({ sections, activeSection, setActiveSection, isCoord, teams, activeTeam, setActiveTeam }) {
  const [showMore, setShowMore] = React.useState(false);
  const storageKey = "mgd_nav_recientes_" + (isCoord ? "coord" : "entrenador");
  const [recientes, setRecientes] = React.useState(() => {
    try { return JSON.parse(localStorage.getItem(storageKey)) || []; } catch(e) { return []; }
  });

  const defaults = isCoord
    ? ["resumen", "plantilla", "entrenamientos", "partidos"]
    : ["plantilla", "entrenamientos", "partidos", "asistencia"];

  const validIds = sections.map(s => s.id);
  const barIds = [...new Set([...recientes, ...defaults])]
    .filter(id => validIds.includes(id))
    .slice(0, 4);

  // Orden estable: según el orden original de sections, no según recencia
  const main = sections.filter(s => barIds.includes(s.id));
  const more = sections.filter(s => !barIds.includes(s.id));
  const isMoreActive = more.some(s => s.id === activeSection);

  const go = (id) => {
    setActiveSection(id);
    setShowMore(false);
    const nuevos = [id, ...recientes.filter(x => x !== id)].slice(0, 8);
    setRecientes(nuevos);
    try { localStorage.setItem(storageKey, JSON.stringify(nuevos)); } catch(e) {}
  };

  return (
    <>
      {showMore && (
        <div className="md:hidden fixed inset-0 z-40 bg-black/60 overflow-y-auto" style={{ WebkitOverflowScrolling: "touch" }} onClick={() => setShowMore(false)}>
          <div className="min-h-full flex flex-col justify-end">
            <div className="bg-zinc-900 border-t border-zinc-700 rounded-t-2xl"
              style={{ marginBottom: "calc(4rem + env(safe-area-inset-bottom))" }}
              onClick={e => e.stopPropagation()}>
              <div className="w-10 h-1 bg-zinc-700 rounded-full mx-auto my-3 shrink-0" />
              <div className="px-4 pb-4">
                {isCoord && (
                  <div className="mb-4">
                    <p className="text-xs text-zinc-500 uppercase tracking-wider mb-2">Equipo</p>
                    <div className="flex flex-wrap gap-1.5">
                      {teams.map(t => (
                        <button key={t} onClick={() => { setActiveTeam(t); }}
                          className={`px-3 py-1.5 rounded-full text-xs font-semibold border transition-all ${activeTeam === t ? "bg-red-700 border-red-500 text-white" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                          {t}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
                <p className="text-xs text-zinc-500 uppercase tracking-wider mb-2">Más secciones</p>
                <div className="grid grid-cols-3 gap-2">
                  {more.map(s => (
                    <button key={s.id} onClick={() => go(s.id)}
                      className={`flex flex-col items-center gap-1 py-3 rounded-xl border transition-all ${activeSection === s.id ? "bg-red-900/40 border-red-700 text-red-300" : "bg-zinc-800 border-zinc-700 text-zinc-400"}`}>
                      <span className="text-xl">{s.icon}</span>
                      <span className="text-xs font-medium text-center leading-tight">{s.label}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="md:hidden fixed bottom-0 inset-x-0 z-[45] bg-zinc-900 border-t border-zinc-800 flex"
        style={{ paddingBottom: "env(safe-area-inset-bottom)" }}>
        {main.map(s => (
          <button key={s.id} onClick={() => go(s.id)}
            className={`flex-1 flex flex-col items-center gap-0.5 py-2 transition-all ${activeSection === s.id ? "text-red-400" : "text-zinc-500"}`}>
            <span className="text-lg">{s.icon}</span>
            <span className="text-[10px] font-medium">{s.label.length > 10 ? s.label.slice(0, 9) + "…" : s.label}</span>
            {activeSection === s.id && <span className="w-5 h-0.5 bg-red-500 rounded-full" />}
          </button>
        ))}
        <button onClick={() => setShowMore(v => !v)}
          className={`flex-1 flex flex-col items-center gap-0.5 py-2 transition-all ${showMore || isMoreActive ? "text-red-400" : "text-zinc-500"}`}>
          <span className="text-lg">☰</span>
          <span className="text-[10px] font-medium">Más</span>
          {isMoreActive && !showMore && <span className="w-5 h-0.5 bg-red-500 rounded-full" />}
        </button>
      </div>
    </>
  );
}


